function NavItem({
  href,
  icon,
  label,
  active,
  showDot = false,
}: {
  href:
    | "/dashboard"
    | "/dashboard/explorer"
    | "/dashboard/notifications"
    | "/dashboard/settings";
  icon: React.ReactNode;
  label: string;
  active: boolean;
  showDot?: boolean;
}) {
  return (
    <Link
      href={href}
      className={cn(
        "relative flex items-center gap-3 rounded-full px-4 py-2.5 text-sm font-semibold transition",
        active
          ? "bg-[#f6ebda] text-[#f39a22]"
          : "text-[#60718a] hover:bg-[#eef2f7]"
      )}
    >
      <span className="inline-flex h-4 w-4 items-center justify-center">
        {icon}
      </span>
      <span>{label}</span>
      {showDot && (
        <span className="absolute right-3 h-1.5 w-1.5 rounded-full bg-[#f05353]" />
      )}
    </Link>
  );
}

